func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if value != "" {
			return value
		}
	}
	return ""
}

func rawMap(items map[string]json.RawMessage) gin.H {
	result := make(gin.H, len(items))
	for name, value := range items {
		result[name] = value
	}
	return result
}

